import re
import shutil
import subprocess
from datetime import datetime
from pathlib import Path

from langchain_core.tools import tool

EXPORT_SCRIPT = Path("/opt/shop/scripts/export_orders.py")
OUTPUT_DIR = Path("/var/shop/exports/tmp")
ARCHIVE_ROOT = Path("/var/shop/exports/archive")
_STORE_RE = re.compile(r"^[a-z0-9][a-z0-9-]{1,31}$")


def _parse_date(value):
    try:
        return datetime.strptime(value, "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return None


@tool
def run_order_export_and_archive(start_date: str, end_date: str, store_code: str) -> dict:
    start = _parse_date(start_date)
    if start is None:
        return {"ok": False, "error": f"Invalid start_date: {start_date!r}"}
    end = _parse_date(end_date)
    if end is None:
        return {"ok": False, "error": f"Invalid end_date: {end_date!r}"}
    if end < start:
        return {"ok": False, "error": "end_date must not be before start_date"}
    if (end - start).days > 92:
        return {"ok": False, "error": "Date range may not exceed 92 days"}
    if not store_code or not _STORE_RE.match(store_code):
        return {"ok": False, "error": f"Invalid store_code: {store_code!r}"}
    if not EXPORT_SCRIPT.exists():
        return {"ok": False, "error": "Export script not found on this host"}

    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    filename = f"orders_{store_code}_{start.isoformat()}_{end.isoformat()}.csv"
    output_path = OUTPUT_DIR / filename

    proc = subprocess.run(
        [
            "python3",
            str(EXPORT_SCRIPT),
            "--store", store_code,
            "--from", start.isoformat(),
            "--to", end.isoformat(),
            "--out", str(output_path),
        ],
        capture_output=True,
        text=True,
        timeout=900,
    )
    if proc.returncode != 0:
        return {"ok": False, "error": "Export script failed", "stderr": proc.stderr[-2000:]}
    if not output_path.exists():
        return {"ok": False, "error": "Export finished but no output file was produced"}

    archive_dir = ARCHIVE_ROOT / store_code / start.strftime("%Y-%m")
    archive_dir.mkdir(parents=True, exist_ok=True)
    destination = archive_dir / filename
    shutil.move(str(output_path), str(destination))

    return {
        "ok": True,
        "archived_path": str(destination),
        "script_output": proc.stdout[-1000:],
    }

import sqlite3
from datetime import datetime, timezone

from agents import function_tool

DB_PATH = "/var/shop/orders.db"


@function_tool
def grant_agent_order_access(order_id: str, agent_email: str, level: str) -> dict:
    if level not in ("view", "edit"):
        return {"error": "level must be 'view' or 'edit'"}
    c = sqlite3.connect(DB_PATH)
    c.row_factory = sqlite3.Row
    try:
        o = c.execute(
            "SELECT id, status, customer_email, total_cents FROM orders WHERE id = ?",
            (order_id,),
        ).fetchone()
        if o is None:
            return {"error": f"Order {order_id} not found"}
        ts = datetime.now(timezone.utc).isoformat()
        c.execute(
            "INSERT INTO order_access (order_id, agent_email, level, granted_at) VALUES (?, ?, ?, ?) "
            "ON CONFLICT(order_id, agent_email) DO UPDATE SET level = excluded.level, granted_at = excluded.granted_at",
            (order_id, agent_email.lower(), level, ts),
        )
        c.commit()
        return {"order": dict(o), "agent_email": agent_email.lower(), "level": level, "granted_at": ts}
    finally:
        c.close()

import sqlite3

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("orders")
DB_PATH = "/var/shop/orders.db"


@mcp.tool()
def update_order_shipping_address(order_id: str, line1: str, city: str, postal_code: str, country: str, line2: str = "") -> dict:
    cc = country.strip().upper()
    if len(cc) != 2:
        return {"error": "country must be a two-letter code"}
    c = sqlite3.connect(DB_PATH)
    try:
        r = c.execute(
            "UPDATE orders SET ship_line1 = ?, ship_line2 = ?, ship_city = ?, ship_postal = ?, ship_country = ? "
            "WHERE id = ? AND status IN ('pending', 'paid', 'processing')",
            (line1.strip(), line2.strip(), city.strip(), postal_code.strip(), cc, order_id),
        )
        c.commit()
        if r.rowcount == 0:
            return {"error": f"Order {order_id} not found or already shipped"}
        a = {"line1": line1.strip(), "line2": line2.strip(), "city": city.strip(), "postal_code": postal_code.strip(), "country": cc}
        return {"order_id": order_id, "shipping_address": a}
    finally:
        c.close()
